            data_column_sidecar,
            block_seen,
            origin,
            true,
            parent_info,
            || Some(state),
            metrics,
        )
    } else {
        self.validate_data_column_sidecar_with_state(
            data_column_sidecar,
            block_seen,
            origin,
            true,
            parent_info,
            || {
                self.state_cache.existing_state_at_slot(
                    self,
                    block_header.parent_root,
                    block_header.slot,
                )
            },
            metrics,
        )
    }
}

